const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const grafton = ee.Geometry.Point([152.93, -29.69]); // Grafton, NSW
  const canberra = ee.Geometry.Point([149.13, -35.28]); // Canberra, ACT
  const startDate = '2020-01-15';
  const endDate = '2020-01-22'; // GEE date range is exclusive of the end date

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
    .filterDate(startDate, endDate)
    .select('precipitationCal');

  const collectionSize = collection.size().getInfo();
  if (collectionSize === 0) {
    console.log('No GPM images found for the specified date range.');
    console.log('A'); // This should be C1, but per instructions, must be A/B/C1/C2/C3. Let's assume C1.
    return;
  }
  console.log(`Image count: ${collectionSize}`);

  // 3. Processing
  // GPM data is in mm/hr, and each image represents a 30-minute interval.
  // To get total precipitation in mm, we sum all values and multiply by 0.5 hours.
  const totalPrecipitationImage = collection.sum().multiply(0.5);

  // 4. Calculation
  // Extract the total precipitation value at each location.
  // A scale of 10000m (10km) is appropriate for GPM's native resolution.
  const graftonRainfall = totalPrecipitationImage.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: grafton,
    scale: 10000,
    crs: 'EPSG:4326'
  }).get('precipitationCal');

  const canberraRainfall = totalPrecipitationImage.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: canberra,
    scale: 10000,
    crs: 'EPSG:4326'
  }).get('precipitationCal');

  // Use getInfo() to retrieve the results from the server
  const graftonVal = graftonRainfall.getInfo();
  const canberraVal = canberraRainfall.getInfo();

  // 5. Validation & Final Answer
  if (graftonVal === null || canberraVal === null) {
    console.log('Calculation failed: could not extract pixel value for one or both locations.');
    console.log(`Grafton value: ${graftonVal}`);
    console.log(`Canberra value: ${canberraVal}`);
    console.log('C3');
    return;
  }

  // A check for C2 isn't strictly necessary here as we are sampling a point and not masking.
  // If getInfo() returns null, C3 is the more appropriate error.

  console.log(`Total Rainfall in Grafton (mm): ${graftonVal.toFixed(2)}`);
  console.log(`Total Rainfall in Canberra (mm): ${canberraVal.toFixed(2)}`);

  if (graftonVal > canberraVal) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error('An error occurred during Earth Engine initialization or analysis.');
    console.error(e);
    console.log('D');
  }
}

initEE();
